{
  "name": "trackeros",
  "version": "0.1.0",
  "tier": "tier1",
  "templateId": "corporate-ops-web-mobile",
  "description": "Trackeros — a corporate operations web and mobile platform for\n  mid-sized companies. Provides employee self-service (leave\n  requests, balances, expense claims), manager workflows\n  (approvals, team views, time-off calendars), and HR admin\n  surfaces (leave policy configuration, balance accruals,\n  audit reports).\n  \n  Backend: TypeScript on Node 20 (Fastify), PostgreSQL via\n  Knex migrations + a thin repository layer, BullMQ for\n  background jobs (accrual schedulers, notification fanout).\n  Module structure: src/modules/<name>/<name>.{model,\n  repository,service,controller,routes}.ts. Domain modules\n  include leave, balance, employee, policy, notification.\n  Shared utilities under src/shared/ (db connection, base\n  repository, error types).\n  \n  Frontend: React + Vite SPA for the web client, React Native\n  for the mobile client (shared @trackeros/contracts package\n  for the typed REST surface). Auth via JWT against the\n  backend's /auth endpoints; identity comes from corporate\n  OIDC in production and from local users in development.\n  \n  Tests: Jest for unit + integration. CI on GitHub Actions\n  runs lint (ESLint) + typecheck (tsc --noEmit) + unit tests +\n  a Semgrep security pass on every PR. Conventional Commits +\n  squash-merge. Strict TypeScript (no implicit any, strict\n  null checks).",
  "stack": {
    "language": "TypeScript",
    "nodeVersion": "20",
    "packageManager": "npm",
    "testFramework": "Jest",
    "framework": "Fastify",
    "frontend": "React Native",
    "database": "PostgreSQL",
    "architectureStyle": "modular-monolith"
  },
  "adapters": {
    "database": {
      "type": "postgres",
      "configKey": "DATABASE_URL"
    },
    "queue": {
      "type": "bullmq",
      "configKey": "REDIS_URL"
    },
    "llm": {
      "type": "azure-openai",
      "configKey": "LLM_BASE_URL"
    }
  },
  "_comment_gate": "CI (build/tests/lint/security) runs first via pipeline.adapter. The Gestalt LLM gate (constraint-agent + review-agent) runs after CI passes as a pre-merge architectural review.",
  "qualityGate": {
    "required": [
      "constraint-check",
      "design-review"
    ],
    "blockingSignals": [
      "GOLDEN_PRINCIPLE_BREACH",
      "CONSTRAINT_VIOLATION"
    ],
    "autoResolvableSignals": [
      "LINT_FAILURE",
      "TEST_FAILURE"
    ],
    "maxRetries": 3
  },
  "constraints": {
    "rules": [
      {
        "id": "no-any",
        "description": "Use unknown with type guards instead of any",
        "severity": "high"
      },
      {
        "id": "no-direct-db-outside-repository",
        "description": "Database calls must go through repository pattern",
        "severity": "critical"
      },
      {
        "id": "no-hardcoded-secrets",
        "description": "No hardcoded passwords, API keys, or tokens",
        "severity": "critical"
      },
      {
        "id": "no-gestalt-internal-deps",
        "description": "Do not add @gestalt/* packages as project dependencies — these are Gestalt platform internals not available on npm",
        "severity": "critical"
      }
    ]
  },
  "codeGeneration": {
    "backend": "aider",
    "verification": {
      "buildCmd": "",
      "testCmd": "find src -name '*.ts' -not -name '*.spec.ts' -not -name '*.test.ts' -not -name '*.d.ts' -type f | grep -q . && npm run build && npx jest --passWithNoTests",
      "lintCmd": ""
    }
  },
  "_comment_verification": "MECHANICAL COMPILE GATE: run in the code-agent work dir before commit; a non-zero exit blocks the commit + routes to self-heal so a compile/type error never reaches CI. Installs deps (clones carry no node_modules), guards on source presence so an empty phase exits 0.",
  "verification": {
    "command": "npm install --include=dev --no-audit --no-fund && if find src -name '*.ts' -not -name '*.spec.ts' -not -name '*.test.ts' -not -name '*.d.ts' -type f | grep -q .; then npm run build && npx jest --passWithNoTests; else echo 'no source files to verify'; fi",
    "timeoutSeconds": 900
  },
  "pipeline": {
    "adapter": "github-actions",
    "autoMerge": true,
    "mergeMethod": "squash"
  },
  "prAgent": {
    "enabled": true,
    "blockOnChangesRequested": true,
    "pendingTimeoutSeconds": 90
  },
  "planner": {
    "enabled": true,
    "maxPhasesPerFeature": 10,
    "maxFilesPerPhase": 5,
    "architectureReviewPerPhase": true,
    "maxPhaseRetries": 2,
    "engine": "langgraph"
  },
  "tokenManagement": {
    "promptCompressionThreshold": 6000,
    "maxRetryBudgetMultiplier": 2.0,
    "enableDynamicBudget": true,
    "enableScopeReduction": true
  },
  "maintenance": {
    "driftCheck": {
      "enabled": true,
      "scheduleUtc": "0 2 * * *"
    },
    "alignmentCheck": {
      "enabled": true,
      "scheduleUtc": "0 3 * * *"
    },
    "gcCheck": {
      "enabled": true,
      "scheduleUtc": "0 4 * * 5"
    },
    "monitoring": {
      "adapter": "noop",
      "enabled": true,
      "connectionConfig": {},
      "thresholds": {
        "errorRatePercent": 5.0,
        "latencyP99Ms": 2000,
        "alertCountWindow": "1h",
        "alertCountThreshold": 10
      }
    }
  },
  "identity": {
    "providers": [
      {
        "type": "local",
        "enabled": true,
        "warningBanner": true,
        "allowedInProduction": false
      }
    ],
    "roleMapping": [],
    "defaultRole": null,
    "sessionTtlMinutes": 480
  }
}

import { LeaveBalance, BalanceStatus } from './balance.model';
import { IBalanceRepository } from './balance.repository';
import { IBalanceService, CreateBalanceDto } from './balance.service.interface';

export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ValidationError';
  }
}

function computeRemainingDays(totalEntitlement: number, usedDays: number): number {
  return Math.floor(totalEntitlement - usedDays);
}

function deriveStatus(remainingDays: number): BalanceStatus {
  return remainingDays > 0 ? BalanceStatus.ACTIVE : BalanceStatus.EXHAUSTED;
}

export class BalanceService implements IBalanceService {
  constructor(private readonly repository: IBalanceRepository) {}

  async getById(id: string): Promise<LeaveBalance | null> {
    return this.repository.findById(id);
  }

  async getByEmployee(employeeId: string): Promise<LeaveBalance[]> {
    return this.repository.findByEmployee(employeeId);
  }

  async getByEmployeeAndPolicy(employeeId: string, leavePolicyId: string): Promise<LeaveBalance | null> {
    return this.repository.findByEmployeeAndPolicy(employeeId, leavePolicyId);
  }

  async create(data: CreateBalanceDto): Promise<LeaveBalance> {
    if (!data.employeeId || data.employeeId.trim().length === 0) {
      throw new ValidationError('employeeId is required and must not be empty');
    }

    if (!data.leavePolicyId || data.leavePolicyId.trim().length === 0) {
      throw new ValidationError('leavePolicyId is required and must not be empty');
    }

    if (typeof data.totalEntitlement !== 'number' || data.totalEntitlement <= 0 || !Number.isFinite(data.totalEntitlement)) {
      throw new ValidationError('totalEntitlement must be a positive number');
    }

    if (typeof data.fiscalYear !== 'number' || data.fiscalYear <= 0 || !Number.isInteger(data.fiscalYear)) {
      throw new ValidationError('fiscalYear must be a positive integer');
    }

    const totalEntitlement = Math.floor(data.totalEntitlement);
    const usedDays = 0;
    const remainingDays = totalEntitlement;

    return this.repository.create({
      employeeId: data.employeeId.trim(),
      leavePolicyId: data.leavePolicyId.trim(),
      totalEntitlement,
      usedDays,
      remainingDays,
      fiscalYear: data.fiscalYear,
      status: BalanceStatus.ACTIVE,
    });
  }

  async deductDays(id: string, days: number): Promise<LeaveBalance> {
    if (typeof days !== 'number' || days <= 0 || !Number.isFinite(days)) {
      throw new ValidationError('days must be a positive number');
    }

    const balance = await this.repository.findById(id);
    if (!balance) {
      throw new ValidationError('Balance not found');
    }

    if (balance.status === BalanceStatus.CLOSED) {
      throw new ValidationError('Cannot deduct from a CLOSED balance');
    }

    if (balance.status !== BalanceStatus.ACTIVE) {
      throw new ValidationError('Cannot deduct from a non-ACTIVE balance');
    }

    const daysToDeduct = Math.floor(days);
    if (balance.remainingDays < daysToDeduct) {
      throw new ValidationError(
        `Insufficient balance: requested ${daysToDeduct} days but only ${balance.remainingDays} remaining`,
      );
    }

    const newUsedDays = balance.usedDays + daysToDeduct;
    const newRemainingDays = computeRemainingDays(balance.totalEntitlement, newUsedDays);
    const newStatus = deriveStatus(newRemainingDays);

    return this.repository.update(id, {
      usedDays: newUsedDays,
      remainingDays: newRemainingDays,
      status: newStatus,
      updatedAt: new Date(),
    }) as Promise<LeaveBalance>;
  }

  async restoreDays(id: string, days: number): Promise<LeaveBalance> {
    if (typeof days !== 'number' || days <= 0 || !Number.isFinite(days)) {
      throw new ValidationError('days must be a positive number');
    }

    const balance = await this.repository.findById(id);
    if (!balance) {
      throw new ValidationError('Balance not found');
    }

    if (balance.status === BalanceStatus.CLOSED) {
      throw new ValidationError('Cannot restore to a CLOSED balance');
    }

    const daysToRestore = Math.floor(days);
    if (balance.usedDays < daysToRestore) {
      throw new ValidationError(
        `Cannot restore ${daysToRestore} days: only ${balance.usedDays} days used`,
      );
    }

    const newUsedDays = balance.usedDays - daysToRestore;
    const newRemainingDays = computeRemainingDays(balance.totalEntitlement, newUsedDays);
    const newStatus = deriveStatus(newRemainingDays);

    return this.repository.update(id, {
      usedDays: newUsedDays,
      remainingDays: newRemainingDays,
      status: newStatus,
      updatedAt: new Date(),
    }) as Promise<LeaveBalance>;
  }

  async hasSufficientBalance(employeeId: string, leavePolicyId: string, requestedDays: number): Promise<boolean> {
    const balance = await this.repository.findByEmployeeAndPolicy(employeeId, leavePolicyId);
    if (!balance) {
      return false;
    }

    if (balance.status !== BalanceStatus.ACTIVE) {
      return false;
    }

    const days = Math.floor(requestedDays);
    return balance.remainingDays >= days;
  }
}

import { BalanceService, ValidationError } from '../../../../src/modules/balance/balance.service';
import { IBalanceRepository } from '../../../../src/modules/balance/balance.repository';
import { LeaveBalance, BalanceStatus } from '../../../../src/modules/balance/balance.model';
import { CreateBalanceDto } from '../../../../src/modules/balance/balance.service.interface';

function makeBalance(overrides: Partial<LeaveBalance> = {}): LeaveBalance {
  return {
    id: 'balance-1',
    employeeId: 'emp-1',
    leavePolicyId: 'policy-1',
    totalEntitlement: 20,
    usedDays: 0,
    remainingDays: 20,
    fiscalYear: 2026,
    status: BalanceStatus.ACTIVE,
    createdAt: new Date('2026-01-01'),
    updatedAt: new Date('2026-01-01'),
    ...overrides,
  };
}

function makeMockRepo(): jest.Mocked<IBalanceRepository> {
  return {
    findById: jest.fn(),
    findByEmployee: jest.fn(),
    findByEmployeeAndPolicy: jest.fn(),
    findByEmployeeAndFiscalYear: jest.fn(),
    create: jest.fn(),
    update: jest.fn(),
    delete: jest.fn(),
  };
}

describe('BalanceService', () => {
  let service: BalanceService;
  let repo: jest.Mocked<IBalanceRepository>;

  beforeEach(() => {
    repo = makeMockRepo();
    service = new BalanceService(repo);
  });

  describe('getById', () => {
    it('should return balance when found', async () => {
      const balance = makeBalance();
      repo.findById.mockResolvedValue(balance);

      const result = await service.getById('balance-1');
      expect(result).toEqual(balance);
      expect(repo.findById).toHaveBeenCalledWith('balance-1');
    });

    it('should return null when not found', async () => {
      repo.findById.mockResolvedValue(null);

      const result = await service.getById('nonexistent');
      expect(result).toBeNull();
    });
  });

  describe('getByEmployee', () => {
    it('should return balances for an employee', async () => {
      const balances = [makeBalance(), makeBalance({ id: 'balance-2', leavePolicyId: 'policy-2' })];
      repo.findByEmployee.mockResolvedValue(balances);

      const result = await service.getByEmployee('emp-1');
      expect(result).toEqual(balances);
      expect(repo.findByEmployee).toHaveBeenCalledWith('emp-1');
    });

    it('should return empty array when no balances', async () => {
      repo.findByEmployee.mockResolvedValue([]);

      const result = await service.getByEmployee('emp-1');
      expect(result).toEqual([]);
    });
  });

  describe('getByEmployeeAndPolicy', () => {
    it('should return balance for employee+policy', async () => {
      const balance = makeBalance();
      repo.findByEmployeeAndPolicy.mockResolvedValue(balance);

      const result = await service.getByEmployeeAndPolicy('emp-1', 'policy-1');
      expect(result).toEqual(balance);
      expect(repo.findByEmployeeAndPolicy).toHaveBeenCalledWith('emp-1', 'policy-1');
    });

    it('should return null when not found', async () => {
      repo.findByEmployeeAndPolicy.mockResolvedValue(null);

      const result = await service.getByEmployeeAndPolicy('emp-1', 'policy-1');
      expect(result).toBeNull();
    });
  });

  describe('create', () => {
    const validDto: CreateBalanceDto = {
      employeeId: 'emp-1',
      leavePolicyId: 'policy-1',
      totalEntitlement: 20,
      fiscalYear: 2026,
    };

    it('should create a balance with valid data', async () => {
      const created = makeBalance();
      repo.create.mockResolvedValue(created);

      const result = await service.create(validDto);
      expect(result).toEqual(created);
      expect(repo.create).toHaveBeenCalledWith({
        employeeId: 'emp-1',
        leavePolicyId: 'policy-1',
        totalEntitlement: 20,
        usedDays: 0,
        remainingDays: 20,
        fiscalYear: 2026,
        status: BalanceStatus.ACTIVE,
      });
    });

    it('should floor fractional totalEntitlement', async () => {
      const created = makeBalance({ totalEntitlement: 15, remainingDays: 15 });
      repo.create.mockResolvedValue(created);

      await service.create({ ...validDto, totalEntitlement: 15.7 });
      expect(repo.create).toHaveBeenCalledWith(
        expect.objectContaining({ totalEntitlement: 15, remainingDays: 15 }),
      );
    });

    it('should reject when employeeId is empty', async () => {
      await expect(service.create({ ...validDto, employeeId: '' }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, employeeId: '  ' }))
        .rejects.toThrow(ValidationError);
    });

    it('should reject when leavePolicyId is empty', async () => {
      await expect(service.create({ ...validDto, leavePolicyId: '' }))
        .rejects.toThrow(ValidationError);
    });

    it('should reject when totalEntitlement is not positive', async () => {
      await expect(service.create({ ...validDto, totalEntitlement: 0 }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, totalEntitlement: -5 }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, totalEntitlement: NaN }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, totalEntitlement: Infinity }))
        .rejects.toThrow(ValidationError);
    });

    it('should reject when fiscalYear is not a positive integer', async () => {
      await expect(service.create({ ...validDto, fiscalYear: 0 }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, fiscalYear: -2026 }))
        .rejects.toThrow(ValidationError);
      await expect(service.create({ ...validDto, fiscalYear: 2026.5 }))
        .rejects.toThrow(ValidationError);
    });

    it('should trim whitespace from employeeId and leavePolicyId', async () => {
      const created = makeBalance();
      repo.create.mockResolvedValue(created);

      await service.create({ ...validDto, employeeId: '  emp-1  ', leavePolicyId: '  policy-1  ' });
      expect(repo.create).toHaveBeenCalledWith(
        expect.objectContaining({ employeeId: 'emp-1', leavePolicyId: 'policy-1' }),
      );
    });
  });

  describe('deductDays', () => {
    it('should deduct days and recalculate remainingDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 0, remainingDays: 20 });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 5, remainingDays: 15 });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      const result = await service.deductDays('balance-1', 5);
      expect(result).toEqual(updated);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 5,
        remainingDays: 15,
        status: BalanceStatus.ACTIVE,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should transition to EXHAUSTED when remainingDays reaches 0', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 15, remainingDays: 5 });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 20, remainingDays: 0, status: BalanceStatus.EXHAUSTED });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      const result = await service.deductDays('balance-1', 5);
      expect(result.status).toBe(BalanceStatus.EXHAUSTED);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 20,
        remainingDays: 0,
        status: BalanceStatus.EXHAUSTED,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should floor fractional days', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 0, remainingDays: 20 });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 3, remainingDays: 17 });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      await service.deductDays('balance-1', 3.7);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 3,
        remainingDays: 17,
        status: BalanceStatus.ACTIVE,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should throw when days <= 0', async () => {
      await expect(service.deductDays('balance-1', 0))
        .rejects.toThrow(ValidationError);
      await expect(service.deductDays('balance-1', -1))
        .rejects.toThrow(ValidationError);
      await expect(service.deductDays('balance-1', NaN))
        .rejects.toThrow(ValidationError);
    });

    it('should throw when balance not found', async () => {
      repo.findById.mockResolvedValue(null);

      await expect(service.deductDays('nonexistent', 5))
        .rejects.toThrow(ValidationError);
    });

    it('should throw when balance is CLOSED', async () => {
      const balance = makeBalance({ status: BalanceStatus.CLOSED });
      repo.findById.mockResolvedValue(balance);

      await expect(service.deductDays('balance-1', 5))
        .rejects.toThrow('Cannot deduct from a CLOSED balance');
    });

    it('should throw when balance is EXHAUSTED', async () => {
      const balance = makeBalance({ status: BalanceStatus.EXHAUSTED, remainingDays: 0 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.deductDays('balance-1', 5))
        .rejects.toThrow('Cannot deduct from a non-ACTIVE balance');
    });

    it('should throw when insufficient remainingDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 18, remainingDays: 2 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.deductDays('balance-1', 5))
        .rejects.toThrow('Insufficient balance');
    });

    it('should never produce negative remainingDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 19, remainingDays: 1 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.deductDays('balance-1', 2))
        .rejects.toThrow('Insufficient balance');
      expect(repo.update).not.toHaveBeenCalled();
    });
  });

  describe('restoreDays', () => {
    it('should restore days and recalculate remainingDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 10, remainingDays: 10 });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 5, remainingDays: 15 });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      const result = await service.restoreDays('balance-1', 5);
      expect(result).toEqual(updated);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 5,
        remainingDays: 15,
        status: BalanceStatus.ACTIVE,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should transition from EXHAUSTED back to ACTIVE when remainingDays > 0', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 20, remainingDays: 0, status: BalanceStatus.EXHAUSTED });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 15, remainingDays: 5, status: BalanceStatus.ACTIVE });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      const result = await service.restoreDays('balance-1', 5);
      expect(result.status).toBe(BalanceStatus.ACTIVE);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 15,
        remainingDays: 5,
        status: BalanceStatus.ACTIVE,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should floor fractional days', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 10, remainingDays: 10 });
      const updated = makeBalance({ totalEntitlement: 20, usedDays: 7, remainingDays: 13 });
      repo.findById.mockResolvedValue(balance);
      repo.update.mockResolvedValue(updated);

      await service.restoreDays('balance-1', 3.7);
      expect(repo.update).toHaveBeenCalledWith('balance-1', {
        usedDays: 7,
        remainingDays: 13,
        status: BalanceStatus.ACTIVE,
        updatedAt: expect.any(Date) as Date,
      });
    });

    it('should throw when days <= 0', async () => {
      await expect(service.restoreDays('balance-1', 0))
        .rejects.toThrow(ValidationError);
      await expect(service.restoreDays('balance-1', -1))
        .rejects.toThrow(ValidationError);
      await expect(service.restoreDays('balance-1', NaN))
        .rejects.toThrow(ValidationError);
    });

    it('should throw when balance not found', async () => {
      repo.findById.mockResolvedValue(null);

      await expect(service.restoreDays('nonexistent', 5))
        .rejects.toThrow(ValidationError);
    });

    it('should throw when balance is CLOSED', async () => {
      const balance = makeBalance({ status: BalanceStatus.CLOSED, usedDays: 10 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.restoreDays('balance-1', 5))
        .rejects.toThrow('Cannot restore to a CLOSED balance');
    });

    it('should throw when usedDays < days (cannot restore more than used)', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 3, remainingDays: 17 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.restoreDays('balance-1', 5))
        .rejects.toThrow('Cannot restore 5 days: only 3 days used');
      expect(repo.update).not.toHaveBeenCalled();
    });

    it('should never produce negative usedDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 0, remainingDays: 20 });
      repo.findById.mockResolvedValue(balance);

      await expect(service.restoreDays('balance-1', 1))
        .rejects.toThrow('Cannot restore 1 days: only 0 days used');
      expect(repo.update).not.toHaveBeenCalled();
    });
  });

  describe('hasSufficientBalance', () => {
    it('should return true when balance exists and remainingDays >= requestedDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 5, remainingDays: 15 });
      repo.findByEmployeeAndPolicy.mockResolvedValue(balance);

      const result = await service.hasSufficientBalance('emp-1', 'policy-1', 10);
      expect(result).toBe(true);
    });

    it('should return true when remainingDays exactly equals requestedDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 10, remainingDays: 10 });
      repo.findByEmployeeAndPolicy.mockResolvedValue(balance);

      const result = await service.hasSufficientBalance('emp-1', 'policy-1', 10);
      expect(result).toBe(true);
    });

    it('should return false when remainingDays < requestedDays', async () => {
      const balance = makeBalance({ totalEntitlement: 20, usedDays: 18, remainingDays: 2 });
      repo.findByEmployeeAndPolicy.mockResolvedValue(balance);

      const result = await service.hasSufficientBalance('emp-1', 'policy-1', 5);
      expect(result).toBe(false);
    });

    it('should return false when no balance exists (never throws)', async () => {
